-- SCH-1 group 1 — platform billing: real columns instead of workarounds.
--   * platform_invoices.kind (was: "Prorata" line-label prefix), void_reason / voided_at
--     (was: outbox event payload only). ISSUED stays the "open" status (no OPEN value).
--   * payments.receipt_file_id (was: lookup of the latest file named "<receipt_number>.pdf").
--   * subscriptions.pending_plan_id / pending_cycle / pending_effective_at
--     (was: price_snapshot.pendingChange), suspended_at / cancelled_at (was: subscription_events).
-- Sections 1 (DDL) are generated by Prisma; sections 2+ are hand-written.

-- ─────────────────────────── 1. DDL (prisma migrate diff) ───────────────────────────
-- CreateEnum
CREATE TYPE "platform_invoice_kind" AS ENUM ('SUBSCRIPTION', 'RENEWAL', 'PRORATA', 'ADDON', 'MANUAL');

-- AlterTable
ALTER TABLE "payments" ADD COLUMN     "receipt_file_id" UUID;

-- AlterTable
ALTER TABLE "platform_invoices" ADD COLUMN     "kind" "platform_invoice_kind" NOT NULL DEFAULT 'SUBSCRIPTION',
ADD COLUMN     "void_reason" TEXT,
ADD COLUMN     "voided_at" TIMESTAMPTZ(6);

-- AlterTable
ALTER TABLE "subscriptions" ADD COLUMN     "cancelled_at" TIMESTAMPTZ(6),
ADD COLUMN     "pending_cycle" "billing_cycle",
ADD COLUMN     "pending_effective_at" DATE,
ADD COLUMN     "pending_plan_id" UUID,
ADD COLUMN     "suspended_at" TIMESTAMPTZ(6);

-- CreateIndex
CREATE INDEX "subscriptions_pending_plan_id_idx" ON "subscriptions"("pending_plan_id");

-- AddForeignKey
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_pending_plan_id_fkey" FOREIGN KEY ("pending_plan_id") REFERENCES "plans"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ─────────────────────────── 2. Data migration ───────────────────────────
-- 2.1 Invoice kind: prorata invoices were recognised by their line label; the first period
-- invoice of a subscription is SUBSCRIPTION, the following ones RENEWAL, no subscription = MANUAL.
UPDATE "platform_invoices" i SET kind = 'PRORATA'
 WHERE EXISTS (SELECT 1 FROM "platform_invoice_lines" l WHERE l.invoice_id = i.id AND l.label LIKE 'Prorata%');
UPDATE "platform_invoices" SET kind = 'MANUAL' WHERE subscription_id IS NULL AND kind <> 'PRORATA';
UPDATE "platform_invoices" i SET kind = 'RENEWAL'
 WHERE i.kind = 'SUBSCRIPTION' AND i.subscription_id IS NOT NULL
   AND EXISTS (
     SELECT 1 FROM "platform_invoices" o
      WHERE o.subscription_id = i.subscription_id AND o.kind <> 'PRORATA' AND o.id <> i.id
        AND (COALESCE(o.period_start, o.issue_date), o.issue_date, o.number)
          < (COALESCE(i.period_start, i.issue_date), i.issue_date, i.number));

-- 2.2 Void reason / date: taken from the outbox event `platform_invoice.voided` when present.
UPDATE "platform_invoices" i SET
  voided_at = COALESCE(ev.created_at, i.updated_at),
  void_reason = COALESCE(ev.reason, 'migrated')
  FROM (SELECT i2.id, e.created_at, e.payload->>'reason' AS reason
          FROM "platform_invoices" i2
          LEFT JOIN LATERAL (
            SELECT created_at, payload FROM "outbox_events"
             WHERE type = 'platform_invoice.voided' AND payload->>'invoiceId' = i2.id::text
             ORDER BY created_at DESC LIMIT 1) e ON true
         WHERE i2.status = 'VOID') ev
 WHERE i.id = ev.id;

-- 2.4 Scheduled plan change: price_snapshot.pendingChange → columns (dropped from the JSON).
UPDATE "subscriptions" s SET
  pending_plan_id = (s.price_snapshot->'pendingChange'->>'planId')::uuid,
  pending_cycle = (s.price_snapshot->'pendingChange'->>'billingCycle')::"billing_cycle",
  pending_effective_at = (s.price_snapshot->'pendingChange'->>'effectiveAt')::date
 WHERE jsonb_typeof(s.price_snapshot->'pendingChange') = 'object'
   AND s.price_snapshot->'pendingChange'->>'billingCycle' IN ('MONTHLY', 'QUARTERLY', 'YEARLY')
   AND s.price_snapshot->'pendingChange'->>'effectiveAt' ~ '^\d{4}-\d{2}-\d{2}$'
   AND EXISTS (SELECT 1 FROM "plans" p WHERE p.id::text = s.price_snapshot->'pendingChange'->>'planId');
UPDATE "subscriptions" SET price_snapshot = price_snapshot - 'pendingChange'
 WHERE price_snapshot ? 'pendingChange';

-- 2.5 Suspension / cancellation dates: last matching subscription event (fallback updated_at).
UPDATE "subscriptions" s SET suspended_at = COALESCE(
  (SELECT max(created_at) FROM "subscription_events" e WHERE e.subscription_id = s.id AND e.to_status = 'SUSPENDED'
     AND e.from_status IS DISTINCT FROM 'SUSPENDED'), s.updated_at)
 WHERE s.status = 'SUSPENDED';
UPDATE "subscriptions" s SET cancelled_at = COALESCE(
  (SELECT max(created_at) FROM "subscription_events" e WHERE e.subscription_id = s.id AND e.to_status = 'CANCELLED'
     AND e.from_status IS DISTINCT FROM 'CANCELLED'), s.updated_at)
 WHERE s.status = 'CANCELLED';

-- ─────────────────────────── 3. Integrity ───────────────────────────
ALTER TABLE "platform_invoices" ADD CONSTRAINT platform_invoices_void_check
  CHECK ((status = 'VOID') = (voided_at IS NOT NULL) AND (status <> 'VOID' OR void_reason IS NOT NULL));
ALTER TABLE "subscriptions" ADD CONSTRAINT subscriptions_pending_change_check
  CHECK ((pending_plan_id IS NULL) = (pending_cycle IS NULL) AND (pending_plan_id IS NULL) = (pending_effective_at IS NULL));
ALTER TABLE "subscriptions" ADD CONSTRAINT subscriptions_suspended_at_check
  CHECK (status <> 'SUSPENDED' OR suspended_at IS NOT NULL);
ALTER TABLE "subscriptions" ADD CONSTRAINT subscriptions_cancelled_at_check
  CHECK (status <> 'CANCELLED' OR cancelled_at IS NOT NULL);

-- Payments stay immutable; receipt_file_id may be set once (NULL → file), never changed after.
CREATE OR REPLACE FUNCTION hm_payment_guard() RETURNS trigger
  LANGUAGE plpgsql AS $fn$
DECLARE
  allowed text[] := ARRAY['status', 'validated_by', 'validated_at', 'reversed_by', 'reversed_at',
                          'reversal_reason', 'receipt_number', 'receipt_file_id', 'updated_at'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'DELETE on %.% is forbidden: reverse the payment instead', TG_TABLE_SCHEMA, TG_TABLE_NAME
      USING ERRCODE = 'HM001';
  END IF;
  IF (to_jsonb(NEW) - allowed) IS DISTINCT FROM (to_jsonb(OLD) - allowed) THEN
    RAISE EXCEPTION 'UPDATE on %.% may only change: %', TG_TABLE_SCHEMA, TG_TABLE_NAME, array_to_string(allowed, ', ')
      USING ERRCODE = 'HM001';
  END IF;
  IF OLD.receipt_file_id IS NOT NULL AND NEW.receipt_file_id IS DISTINCT FROM OLD.receipt_file_id THEN
    RAISE EXCEPTION 'The receipt file of a payment can only be set once'
      USING ERRCODE = 'HM001';
  END IF;
  IF OLD.receipt_number IS NOT NULL AND NEW.receipt_number IS DISTINCT FROM OLD.receipt_number THEN
    RAISE EXCEPTION 'The receipt number of a payment can only be set once'
      USING ERRCODE = 'HM001';
  END IF;
  RETURN NEW;
END
$fn$;

DROP TRIGGER payments_restrict_update ON "payments";
CREATE TRIGGER payments_restrict_update BEFORE UPDATE OR DELETE ON "payments" FOR EACH ROW
  EXECUTE FUNCTION hm_payment_guard();

-- 4. Receipt file backfill (after the new trigger, which allows it): latest tenant file named
-- "<receipt_number>.pdf".
UPDATE "payments" p SET receipt_file_id = (
    SELECT f.id FROM "files" f
     WHERE f.tenant_id = p.tenant_id AND f.original_name = p.receipt_number || '.pdf'
     ORDER BY f.created_at DESC LIMIT 1)
 WHERE p.receipt_number IS NOT NULL AND p.receipt_file_id IS NULL;
